CREATE FUNCTION public.sp_ebcra_var_base() RETURNS TABLE(base_date_last date, base_val_last double precision, base_date_daily date, base_val_daily double precision, base_date_monthly date, base_val_monthly double precision, base_date_yearly date, base_val_yearly double precision, base_date_2years date, base_val_2years double precision, base_date_3years date, base_val_3years double precision, base_date_5years date, base_val_5years double precision, base_date_10years date, base_val_10years double precision)
    LANGUAGE plpgsql
    AS $$
  BEGIN
      SELECT t.date, t.value INTO base_date_last, base_val_last FROM BCRA_base_monetaria t ORDER BY t.date DESC LIMIT 1;
      SELECT (base_date_last - INTERVAL '1 day'), t.value INTO base_date_daily, base_val_daily FROM BCRA_base_monetaria t WHERE t.date <= (base_date_last - INTERVAL '1 day') ORDER BY t.date
  DESC LIMIT 1;
      SELECT (base_date_last - INTERVAL '1 month'), t.value INTO base_date_monthly, base_val_monthly FROM BCRA_base_monetaria t WHERE t.date <= (base_date_last - INTERVAL '1 month') ORDER BY
   t.date DESC LIMIT 1;
      SELECT (base_date_last - INTERVAL '1 year'), t.value INTO base_date_yearly, base_val_yearly FROM BCRA_base_monetaria t WHERE t.date <= (base_date_last - INTERVAL '1 year') ORDER BY
  t.date DESC LIMIT 1;
      SELECT (base_date_last - INTERVAL '2 years'), t.value INTO base_date_2years, base_val_2years FROM BCRA_base_monetaria t WHERE t.date <= (base_date_last - INTERVAL '2 years') ORDER BY
  t.date DESC LIMIT 1;
      SELECT (base_date_last - INTERVAL '3 years'), t.value INTO base_date_3years, base_val_3years FROM BCRA_base_monetaria t WHERE t.date <= (base_date_last - INTERVAL '3 years') ORDER BY
  t.date DESC LIMIT 1;
      SELECT (base_date_last - INTERVAL '5 years'), t.value INTO base_date_5years, base_val_5years FROM BCRA_base_monetaria t WHERE t.date <= (base_date_last - INTERVAL '5 years') ORDER BY
  t.date DESC LIMIT 1;
      SELECT (base_date_last - INTERVAL '10 years'), t.value INTO base_date_10years, base_val_10years FROM BCRA_base_monetaria t WHERE t.date <= (base_date_last - INTERVAL '10 years') ORDER
  BY t.date DESC LIMIT 1;
      RETURN NEXT;
  END;
  $$;


