    AS $$
BEGIN
    -- activos: Oro, divisas, colocaciones a plazo y otros activos de reserva (id 75)
    SELECT t.date, t.value INTO activos_date_last, activos_val_last FROM bcra_oro_divisas_colocaciones_plazo t ORDER BY t.date DESC LIMIT 1;
    SELECT (activos_date_last - INTERVAL '1 day'),    t.value INTO activos_date_daily,    activos_val_daily    FROM bcra_oro_divisas_colocaciones_plazo t WHERE t.date <= (activos_date_last - INTERVAL '1 day')    ORDER BY t.date DESC LIMIT 1;
    SELECT (activos_date_last - INTERVAL '1 month'),  t.value INTO activos_date_monthly,  activos_val_monthly  FROM bcra_oro_divisas_colocaciones_plazo t WHERE t.date <= (activos_date_last - INTERVAL '1 month')  ORDER BY t.date DESC LIMIT 1;
    SELECT (activos_date_last - INTERVAL '1 year'),   t.value INTO activos_date_yearly,   activos_val_yearly   FROM bcra_oro_divisas_colocaciones_plazo t WHERE t.date <= (activos_date_last - INTERVAL '1 year')   ORDER BY t.date DESC LIMIT 1;
    SELECT (activos_date_last - INTERVAL '2 years'),  t.value INTO activos_date_2years,   activos_val_2years   FROM bcra_oro_divisas_colocaciones_plazo t WHERE t.date <= (activos_date_last - INTERVAL '2 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (activos_date_last - INTERVAL '3 years'),  t.value INTO activos_date_3years,   activos_val_3years   FROM bcra_oro_divisas_colocaciones_plazo t WHERE t.date <= (activos_date_last - INTERVAL '3 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (activos_date_last - INTERVAL '5 years'),  t.value INTO activos_date_5years,   activos_val_5years   FROM bcra_oro_divisas_colocaciones_plazo t WHERE t.date <= (activos_date_last - INTERVAL '5 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (activos_date_last - INTERVAL '10 years'), t.value INTO activos_date_10years,  activos_val_10years  FROM bcra_oro_divisas_colocaciones_plazo t WHERE t.date <= (activos_date_last - INTERVAL '10 years') ORDER BY t.date DESC LIMIT 1;

    -- pase_pas: Divisas-pase pasivo en dólares con el exterior (id 76)
    SELECT t.date, t.value INTO pase_pas_date_last, pase_pas_val_last FROM bcra_divisas_pase_pasivo_exterior t ORDER BY t.date DESC LIMIT 1;
    SELECT (pase_pas_date_last - INTERVAL '1 day'),    t.value INTO pase_pas_date_daily,    pase_pas_val_daily    FROM bcra_divisas_pase_pasivo_exterior t WHERE t.date <= (pase_pas_date_last - INTERVAL '1 day')    ORDER BY t.date DESC LIMIT 1;
    SELECT (pase_pas_date_last - INTERVAL '1 month'),  t.value INTO pase_pas_date_monthly,  pase_pas_val_monthly  FROM bcra_divisas_pase_pasivo_exterior t WHERE t.date <= (pase_pas_date_last - INTERVAL '1 month')  ORDER BY t.date DESC LIMIT 1;
    SELECT (pase_pas_date_last - INTERVAL '1 year'),   t.value INTO pase_pas_date_yearly,   pase_pas_val_yearly   FROM bcra_divisas_pase_pasivo_exterior t WHERE t.date <= (pase_pas_date_last - INTERVAL '1 year')   ORDER BY t.date DESC LIMIT 1;
    SELECT (pase_pas_date_last - INTERVAL '2 years'),  t.value INTO pase_pas_date_2years,   pase_pas_val_2years   FROM bcra_divisas_pase_pasivo_exterior t WHERE t.date <= (pase_pas_date_last - INTERVAL '2 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (pase_pas_date_last - INTERVAL '3 years'),  t.value INTO pase_pas_date_3years,   pase_pas_val_3years   FROM bcra_divisas_pase_pasivo_exterior t WHERE t.date <= (pase_pas_date_last - INTERVAL '3 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (pase_pas_date_last - INTERVAL '5 years'),  t.value INTO pase_pas_date_5years,   pase_pas_val_5years   FROM bcra_divisas_pase_pasivo_exterior t WHERE t.date <= (pase_pas_date_last - INTERVAL '5 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (pase_pas_date_last - INTERVAL '10 years'), t.value INTO pase_pas_date_10years,  pase_pas_val_10years  FROM bcra_divisas_pase_pasivo_exterior t WHERE t.date <= (pase_pas_date_last - INTERVAL '10 years') ORDER BY t.date DESC LIMIT 1;

    -- deg: Asignaciones de DEGS 2009 (id 83)
    SELECT t.date, t.value INTO deg_date_last, deg_val_last FROM bcra_asignaciones_deg_2009 t ORDER BY t.date DESC LIMIT 1;
    SELECT (deg_date_last - INTERVAL '1 day'),    t.value INTO deg_date_daily,    deg_val_daily    FROM bcra_asignaciones_deg_2009 t WHERE t.date <= (deg_date_last - INTERVAL '1 day')    ORDER BY t.date DESC LIMIT 1;
    SELECT (deg_date_last - INTERVAL '1 month'),  t.value INTO deg_date_monthly,  deg_val_monthly  FROM bcra_asignaciones_deg_2009 t WHERE t.date <= (deg_date_last - INTERVAL '1 month')  ORDER BY t.date DESC LIMIT 1;
    SELECT (deg_date_last - INTERVAL '1 year'),   t.value INTO deg_date_yearly,   deg_val_yearly   FROM bcra_asignaciones_deg_2009 t WHERE t.date <= (deg_date_last - INTERVAL '1 year')   ORDER BY t.date DESC LIMIT 1;
    SELECT (deg_date_last - INTERVAL '2 years'),  t.value INTO deg_date_2years,   deg_val_2years   FROM bcra_asignaciones_deg_2009 t WHERE t.date <= (deg_date_last - INTERVAL '2 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (deg_date_last - INTERVAL '3 years'),  t.value INTO deg_date_3years,   deg_val_3years   FROM bcra_asignaciones_deg_2009 t WHERE t.date <= (deg_date_last - INTERVAL '3 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (deg_date_last - INTERVAL '5 years'),  t.value INTO deg_date_5years,   deg_val_5years   FROM bcra_asignaciones_deg_2009 t WHERE t.date <= (deg_date_last - INTERVAL '5 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (deg_date_last - INTERVAL '10 years'), t.value INTO deg_date_10years,  deg_val_10years  FROM bcra_asignaciones_deg_2009 t WHERE t.date <= (deg_date_last - INTERVAL '10 years') ORDER BY t.date DESC LIMIT 1;

    -- res_ex_deg: Reservas excluidas asignaciones DEG 2009 (id 74)
    SELECT t.date, t.value INTO res_ex_deg_date_last, res_ex_deg_val_last FROM bcra_reservas_excluidas_deg_2009 t ORDER BY t.date DESC LIMIT 1;
    SELECT (res_ex_deg_date_last - INTERVAL '1 day'),    t.value INTO res_ex_deg_date_daily,    res_ex_deg_val_daily    FROM bcra_reservas_excluidas_deg_2009 t WHERE t.date <= (res_ex_deg_date_last - INTERVAL '1 day')    ORDER BY t.date DESC LIMIT 1;
    SELECT (res_ex_deg_date_last - INTERVAL '1 month'),  t.value INTO res_ex_deg_date_monthly,  res_ex_deg_val_monthly  FROM bcra_reservas_excluidas_deg_2009 t WHERE t.date <= (res_ex_deg_date_last - INTERVAL '1 month')  ORDER BY t.date DESC LIMIT 1;
    SELECT (res_ex_deg_date_last - INTERVAL '1 year'),   t.value INTO res_ex_deg_date_yearly,   res_ex_deg_val_yearly   FROM bcra_reservas_excluidas_deg_2009 t WHERE t.date <= (res_ex_deg_date_last - INTERVAL '1 year')   ORDER BY t.date DESC LIMIT 1;
    SELECT (res_ex_deg_date_last - INTERVAL '2 years'),  t.value INTO res_ex_deg_date_2years,   res_ex_deg_val_2years   FROM bcra_reservas_excluidas_deg_2009 t WHERE t.date <= (res_ex_deg_date_last - INTERVAL '2 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (res_ex_deg_date_last - INTERVAL '3 years'),  t.value INTO res_ex_deg_date_3years,   res_ex_deg_val_3years   FROM bcra_reservas_excluidas_deg_2009 t WHERE t.date <= (res_ex_deg_date_last - INTERVAL '3 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (res_ex_deg_date_last - INTERVAL '5 years'),  t.value INTO res_ex_deg_date_5years,   res_ex_deg_val_5years   FROM bcra_reservas_excluidas_deg_2009 t WHERE t.date <= (res_ex_deg_date_last - INTERVAL '5 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (res_ex_deg_date_last - INTERVAL '10 years'), t.value INTO res_ex_deg_date_10years,  res_ex_deg_val_10years  FROM bcra_reservas_excluidas_deg_2009 t WHERE t.date <= (res_ex_deg_date_last - INTERVAL '10 years') ORDER BY t.date DESC LIMIT 1;

    RETURN NEXT;
END;
$$;


