CREATE FUNCTION public.sp_ebcra_var_componentes() RETURNS TABLE(circ_date_last date, circ_val_last double precision, circ_date_daily date, circ_val_daily double precision, circ_date_monthly date, circ_val_monthly double precision, circ_date_yearly date, circ_val_yearly double precision, circ_date_2years date, circ_val_2years double precision, circ_date_3years date, circ_val_3years double precision, circ_date_5years date, circ_val_5years double precision, circ_date_10years date, circ_val_10years double precision, bill_date_last date, bill_val_last double precision, bill_date_daily date, bill_val_daily double precision, bill_date_monthly date, bill_val_monthly double precision, bill_date_yearly date, bill_val_yearly double precision, bill_date_2years date, bill_val_2years double precision, bill_date_3years date, bill_val_3years double precision, bill_date_5years date, bill_val_5years double precision, bill_date_10years date, bill_val_10years double precision, ef_date_last date, ef_val_last double precision, ef_date_daily date, ef_val_daily double precision, ef_date_monthly date, ef_val_monthly double precision, ef_date_yearly date, ef_val_yearly double precision, ef_date_2years date, ef_val_2years double precision, ef_date_3years date, ef_val_3years double precision, ef_date_5years date, ef_val_5years double precision, ef_date_10years date, ef_val_10years double precision, dep_date_last date, dep_val_last double precision, dep_date_daily date, dep_val_daily double precision, dep_date_monthly date, dep_val_monthly double precision, dep_date_yearly date, dep_val_yearly double precision, dep_date_2years date, dep_val_2years double precision, dep_date_3years date, dep_val_3years double precision, dep_date_5years date, dep_val_5years double precision, dep_date_10years date, dep_val_10years double precision)
    LANGUAGE plpgsql
    AS $$
BEGIN
    SELECT t.date, t.value INTO circ_date_last, circ_val_last FROM BCRA_circulacion_monetaria t ORDER BY t.date DESC LIMIT 1;
    SELECT (circ_date_last - INTERVAL '1 day'), t.value INTO circ_date_daily, circ_val_daily FROM BCRA_circulacion_monetaria t WHERE t.date <= (circ_date_last - INTERVAL '1 day') ORDER BY t.date DESC LIMIT 1;
    SELECT (circ_date_last - INTERVAL '1 month'), t.value INTO circ_date_monthly, circ_val_monthly FROM BCRA_circulacion_monetaria t WHERE t.date <= (circ_date_last - INTERVAL '1 month') ORDER BY t.date DESC LIMIT 1;
    SELECT (circ_date_last - INTERVAL '1 year'), t.value INTO circ_date_yearly, circ_val_yearly FROM BCRA_circulacion_monetaria t WHERE t.date <= (circ_date_last - INTERVAL '1 year') ORDER BY t.date DESC LIMIT 1;
    SELECT (circ_date_last - INTERVAL '2 years'), t.value INTO circ_date_2years, circ_val_2years FROM BCRA_circulacion_monetaria t WHERE t.date <= (circ_date_last - INTERVAL '2 years') ORDER BY t.date DESC LIMIT 1;
    SELECT (circ_date_last - INTERVAL '3 years'), t.value INTO circ_date_3years, circ_val_3years FROM BCRA_circulacion_monetaria t WHERE t.date <= (circ_date_last - INTERVAL '3 years') ORDER BY t.date DESC LIMIT 1;
    SELECT (circ_date_last - INTERVAL '5 years'), t.value INTO circ_date_5years, circ_val_5years FROM BCRA_circulacion_monetaria t WHERE t.date <= (circ_date_last - INTERVAL '5 years') ORDER BY t.date DESC LIMIT 1;
    SELECT (circ_date_last - INTERVAL '10 years'), t.value INTO circ_date_10years, circ_val_10years FROM BCRA_circulacion_monetaria t WHERE t.date <= (circ_date_last - INTERVAL '10 years') ORDER BY t.date DESC LIMIT 1;

    SELECT t.date, t.value INTO bill_date_last, bill_val_last FROM BCRA_billetes_y_monedas_publico t ORDER BY t.date DESC LIMIT 1;
    SELECT (bill_date_last - INTERVAL '1 day'), t.value INTO bill_date_daily, bill_val_daily FROM BCRA_billetes_y_monedas_publico t WHERE t.date <= (bill_date_last - INTERVAL '1 day') ORDER BY t.date DESC LIMIT 1;
    SELECT (bill_date_last - INTERVAL '1 month'), t.value INTO bill_date_monthly, bill_val_monthly FROM BCRA_billetes_y_monedas_publico t WHERE t.date <= (bill_date_last - INTERVAL '1 month') ORDER BY t.date DESC LIMIT 1;
    SELECT (bill_date_last - INTERVAL '1 year'), t.value INTO bill_date_yearly, bill_val_yearly FROM BCRA_billetes_y_monedas_publico t WHERE t.date <= (bill_date_last - INTERVAL '1 year') ORDER BY t.date DESC LIMIT 1;
    SELECT (bill_date_last - INTERVAL '2 years'), t.value INTO bill_date_2years, bill_val_2years FROM BCRA_billetes_y_monedas_publico t WHERE t.date <= (bill_date_last - INTERVAL '2 years') ORDER BY t.date DESC LIMIT 1;
    SELECT (bill_date_last - INTERVAL '3 years'), t.value INTO bill_date_3years, bill_val_3years FROM BCRA_billetes_y_monedas_publico t WHERE t.date <= (bill_date_last - INTERVAL '3 years') ORDER BY t.date DESC LIMIT 1;
    SELECT (bill_date_last - INTERVAL '5 years'), t.value INTO bill_date_5years, bill_val_5years FROM BCRA_billetes_y_monedas_publico t WHERE t.date <= (bill_date_last - INTERVAL '5 years') ORDER BY t.date DESC LIMIT 1;
    SELECT (bill_date_last - INTERVAL '10 years'), t.value INTO bill_date_10years, bill_val_10years FROM BCRA_billetes_y_monedas_publico t WHERE t.date <= (bill_date_last - INTERVAL '10 years') ORDER BY t.date DESC LIMIT 1;

    SELECT t.date, t.value INTO ef_date_last, ef_val_last FROM BCRA_efectivo_en_entidades_financieras t ORDER BY t.date DESC LIMIT 1;
    SELECT (ef_date_last - INTERVAL '1 day'), t.value INTO ef_date_daily, ef_val_daily FROM BCRA_efectivo_en_entidades_financieras t WHERE t.date <= (ef_date_last - INTERVAL '1 day') ORDER BY t.date DESC LIMIT 1;
    SELECT (ef_date_last - INTERVAL '1 month'), t.value INTO ef_date_monthly, ef_val_monthly FROM BCRA_efectivo_en_entidades_financieras t WHERE t.date <= (ef_date_last - INTERVAL '1 month') ORDER BY t.date DESC LIMIT 1;
    SELECT (ef_date_last - INTERVAL '1 year'), t.value INTO ef_date_yearly, ef_val_yearly FROM BCRA_efectivo_en_entidades_financieras t WHERE t.date <= (ef_date_last - INTERVAL '1 year') ORDER BY t.date DESC LIMIT 1;
    SELECT (ef_date_last - INTERVAL '2 years'), t.value INTO ef_date_2years, ef_val_2years FROM BCRA_efectivo_en_entidades_financieras t WHERE t.date <= (ef_date_last - INTERVAL '2 years') ORDER BY t.date DESC LIMIT 1;
    SELECT (ef_date_last - INTERVAL '3 years'), t.value INTO ef_date_3years, ef_val_3years FROM BCRA_efectivo_en_entidades_financieras t WHERE t.date <= (ef_date_last - INTERVAL '3 years') ORDER BY t.date DESC LIMIT 1;
    SELECT (ef_date_last - INTERVAL '5 years'), t.value INTO ef_date_5years, ef_val_5years FROM BCRA_efectivo_en_entidades_financieras t WHERE t.date <= (ef_date_last - INTERVAL '5 years') ORDER BY t.date DESC LIMIT 1;
    SELECT (ef_date_last - INTERVAL '10 years'), t.value INTO ef_date_10years, ef_val_10years FROM BCRA_efectivo_en_entidades_financieras t WHERE t.date <= (ef_date_last - INTERVAL '10 years') ORDER BY t.date DESC LIMIT 1;

    SELECT t.date, t.value INTO dep_date_last, dep_val_last FROM BCRA_depositos_bancos_en_cuenta_corriente_del_bcra t ORDER BY t.date DESC LIMIT 1;
    SELECT (dep_date_last - INTERVAL '1 day'), t.value INTO dep_date_daily, dep_val_daily FROM BCRA_depositos_bancos_en_cuenta_corriente_del_bcra t WHERE t.date <= (dep_date_last - INTERVAL '1 day') ORDER BY t.date DESC LIMIT 1;
    SELECT (dep_date_last - INTERVAL '1 month'), t.value INTO dep_date_monthly, dep_val_monthly FROM BCRA_depositos_bancos_en_cuenta_corriente_del_bcra t WHERE t.date <= (dep_date_last - INTERVAL '1 month') ORDER BY t.date DESC LIMIT 1;
    SELECT (dep_date_last - INTERVAL '1 year'), t.value INTO dep_date_yearly, dep_val_yearly FROM BCRA_depositos_bancos_en_cuenta_corriente_del_bcra t WHERE t.date <= (dep_date_last - INTERVAL '1 year') ORDER BY t.date DESC LIMIT 1;
    SELECT (dep_date_last - INTERVAL '2 years'), t.value INTO dep_date_2years, dep_val_2years FROM BCRA_depositos_bancos_en_cuenta_corriente_del_bcra t WHERE t.date <= (dep_date_last - INTERVAL '2 years') ORDER BY t.date DESC LIMIT 1;
    SELECT (dep_date_last - INTERVAL '3 years'), t.value INTO dep_date_3years, dep_val_3years FROM BCRA_depositos_bancos_en_cuenta_corriente_del_bcra t WHERE t.date <= (dep_date_last - INTERVAL '3 years') ORDER BY t.date DESC LIMIT 1;
    SELECT (dep_date_last - INTERVAL '5 years'), t.value INTO dep_date_5years, dep_val_5years FROM BCRA_depositos_bancos_en_cuenta_corriente_del_bcra t WHERE t.date <= (dep_date_last - INTERVAL '5 years') ORDER BY t.date DESC LIMIT 1;
    SELECT (dep_date_last - INTERVAL '10 years'), t.value INTO dep_date_10years, dep_val_10years FROM BCRA_depositos_bancos_en_cuenta_corriente_del_bcra t WHERE t.date <= (dep_date_last - INTERVAL '10 years') ORDER BY t.date DESC LIMIT 1;

    RETURN NEXT;
END;
$$;


