CREATE FUNCTION public.sp_ebcra_var_depositos_por_tipo() RETURNS TABLE(cc_date_last date, cc_val_last double precision, cc_date_daily date, cc_val_daily double precision, cc_date_monthly date, cc_val_monthly double precision, cc_date_yearly date, cc_val_yearly double precision, cc_date_2years date, cc_val_2years double precision, cc_date_3years date, cc_val_3years double precision, cc_date_5years date, cc_val_5years double precision, cc_date_10years date, cc_val_10years double precision, ca_date_last date, ca_val_last double precision, ca_date_daily date, ca_val_daily double precision, ca_date_monthly date, ca_val_monthly double precision, ca_date_yearly date, ca_val_yearly double precision, ca_date_2years date, ca_val_2years double precision, ca_date_3years date, ca_val_3years double precision, ca_date_5years date, ca_val_5years double precision, ca_date_10years date, ca_val_10years double precision, pf_date_last date, pf_val_last double precision, pf_date_daily date, pf_val_daily double precision, pf_date_monthly date, pf_val_monthly double precision, pf_date_yearly date, pf_val_yearly double precision, pf_date_2years date, pf_val_2years double precision, pf_date_3years date, pf_val_3years double precision, pf_date_5years date, pf_val_5years double precision, pf_date_10years date, pf_val_10years double precision, tot_date_last date, tot_val_last double precision, tot_date_daily date, tot_val_daily double precision, tot_date_monthly date, tot_val_monthly double precision, tot_date_yearly date, tot_val_yearly double precision, tot_date_2years date, tot_val_2years double precision, tot_date_3years date, tot_val_3years double precision, tot_date_5years date, tot_val_5years double precision, tot_date_10years date, tot_val_10years double precision)
    LANGUAGE plpgsql
    AS $$
BEGIN
    SELECT t.date, t.value INTO cc_date_last, cc_val_last FROM BCRA_depositos_cuentas_corrientes t ORDER BY t.date DESC LIMIT 1;
    SELECT (cc_date_last - INTERVAL '1 day'), t.value INTO cc_date_daily, cc_val_daily FROM BCRA_depositos_cuentas_corrientes t WHERE t.date <= (cc_date_last - INTERVAL '1 day') ORDER BY t.date DESC LIMIT 1;
    SELECT (cc_date_last - INTERVAL '1 month'), t.value INTO cc_date_monthly, cc_val_monthly FROM BCRA_depositos_cuentas_corrientes t WHERE t.date <= (cc_date_last - INTERVAL '1 month') ORDER BY t.date DESC LIMIT 1;
    SELECT (cc_date_last - INTERVAL '1 year'), t.value INTO cc_date_yearly, cc_val_yearly FROM BCRA_depositos_cuentas_corrientes t WHERE t.date <= (cc_date_last - INTERVAL '1 year') ORDER BY t.date DESC LIMIT 1;
    SELECT (cc_date_last - INTERVAL '2 years'), t.value INTO cc_date_2years, cc_val_2years FROM BCRA_depositos_cuentas_corrientes t WHERE t.date <= (cc_date_last - INTERVAL '2 years') ORDER BY t.date DESC LIMIT 1;
    SELECT (cc_date_last - INTERVAL '3 years'), t.value INTO cc_date_3years, cc_val_3years FROM BCRA_depositos_cuentas_corrientes t WHERE t.date <= (cc_date_last - INTERVAL '3 years') ORDER BY t.date DESC LIMIT 1;
    SELECT (cc_date_last - INTERVAL '5 years'), t.value INTO cc_date_5years, cc_val_5years FROM BCRA_depositos_cuentas_corrientes t WHERE t.date <= (cc_date_last - INTERVAL '5 years') ORDER BY t.date DESC LIMIT 1;
    SELECT (cc_date_last - INTERVAL '10 years'), t.value INTO cc_date_10years, cc_val_10years FROM BCRA_depositos_cuentas_corrientes t WHERE t.date <= (cc_date_last - INTERVAL '10 years') ORDER BY t.date DESC LIMIT 1;

    SELECT t.date, t.value INTO ca_date_last, ca_val_last FROM BCRA_depositos_cajas_ahorro t ORDER BY t.date DESC LIMIT 1;
    SELECT (ca_date_last - INTERVAL '1 day'), t.value INTO ca_date_daily, ca_val_daily FROM BCRA_depositos_cajas_ahorro t WHERE t.date <= (ca_date_last - INTERVAL '1 day') ORDER BY t.date DESC LIMIT 1;
    SELECT (ca_date_last - INTERVAL '1 month'), t.value INTO ca_date_monthly, ca_val_monthly FROM BCRA_depositos_cajas_ahorro t WHERE t.date <= (ca_date_last - INTERVAL '1 month') ORDER BY t.date DESC LIMIT 1;
    SELECT (ca_date_last - INTERVAL '1 year'), t.value INTO ca_date_yearly, ca_val_yearly FROM BCRA_depositos_cajas_ahorro t WHERE t.date <= (ca_date_last - INTERVAL '1 year') ORDER BY t.date DESC LIMIT 1;
    SELECT (ca_date_last - INTERVAL '2 years'), t.value INTO ca_date_2years, ca_val_2years FROM BCRA_depositos_cajas_ahorro t WHERE t.date <= (ca_date_last - INTERVAL '2 years') ORDER BY t.date DESC LIMIT 1;
    SELECT (ca_date_last - INTERVAL '3 years'), t.value INTO ca_date_3years, ca_val_3years FROM BCRA_depositos_cajas_ahorro t WHERE t.date <= (ca_date_last - INTERVAL '3 years') ORDER BY t.date DESC LIMIT 1;
    SELECT (ca_date_last - INTERVAL '5 years'), t.value INTO ca_date_5years, ca_val_5years FROM BCRA_depositos_cajas_ahorro t WHERE t.date <= (ca_date_last - INTERVAL '5 years') ORDER BY t.date DESC LIMIT 1;
    SELECT (ca_date_last - INTERVAL '10 years'), t.value INTO ca_date_10years, ca_val_10years FROM BCRA_depositos_cajas_ahorro t WHERE t.date <= (ca_date_last - INTERVAL '10 years') ORDER BY t.date DESC LIMIT 1;

    SELECT t.date, t.value INTO pf_date_last, pf_val_last FROM BCRA_depositos_a_plazo t ORDER BY t.date DESC LIMIT 1;
    SELECT (pf_date_last - INTERVAL '1 day'), t.value INTO pf_date_daily, pf_val_daily FROM BCRA_depositos_a_plazo t WHERE t.date <= (pf_date_last - INTERVAL '1 day') ORDER BY t.date DESC LIMIT 1;
    SELECT (pf_date_last - INTERVAL '1 month'), t.value INTO pf_date_monthly, pf_val_monthly FROM BCRA_depositos_a_plazo t WHERE t.date <= (pf_date_last - INTERVAL '1 month') ORDER BY t.date DESC LIMIT 1;
    SELECT (pf_date_last - INTERVAL '1 year'), t.value INTO pf_date_yearly, pf_val_yearly FROM BCRA_depositos_a_plazo t WHERE t.date <= (pf_date_last - INTERVAL '1 year') ORDER BY t.date DESC LIMIT 1;
    SELECT (pf_date_last - INTERVAL '2 years'), t.value INTO pf_date_2years, pf_val_2years FROM BCRA_depositos_a_plazo t WHERE t.date <= (pf_date_last - INTERVAL '2 years') ORDER BY t.date DESC LIMIT 1;
    SELECT (pf_date_last - INTERVAL '3 years'), t.value INTO pf_date_3years, pf_val_3years FROM BCRA_depositos_a_plazo t WHERE t.date <= (pf_date_last - INTERVAL '3 years') ORDER BY t.date DESC LIMIT 1;
    SELECT (pf_date_last - INTERVAL '5 years'), t.value INTO pf_date_5years, pf_val_5years FROM BCRA_depositos_a_plazo t WHERE t.date <= (pf_date_last - INTERVAL '5 years') ORDER BY t.date DESC LIMIT 1;
    SELECT (pf_date_last - INTERVAL '10 years'), t.value INTO pf_date_10years, pf_val_10years FROM BCRA_depositos_a_plazo t WHERE t.date <= (pf_date_last - INTERVAL '10 years') ORDER BY t.date DESC LIMIT 1;

    SELECT t.date, t.value INTO tot_date_last, tot_val_last FROM BCRA_depositos_efectivo_entidades_financieras_total t ORDER BY t.date DESC LIMIT 1;
    SELECT (tot_date_last - INTERVAL '1 day'), t.value INTO tot_date_daily, tot_val_daily FROM BCRA_depositos_efectivo_entidades_financieras_total t WHERE t.date <= (tot_date_last - INTERVAL '1 day') ORDER BY t.date DESC LIMIT 1;
    SELECT (tot_date_last - INTERVAL '1 month'), t.value INTO tot_date_monthly, tot_val_monthly FROM BCRA_depositos_efectivo_entidades_financieras_total t WHERE t.date <= (tot_date_last - INTERVAL '1 month') ORDER BY t.date DESC LIMIT 1;
    SELECT (tot_date_last - INTERVAL '1 year'), t.value INTO tot_date_yearly, tot_val_yearly FROM BCRA_depositos_efectivo_entidades_financieras_total t WHERE t.date <= (tot_date_last - INTERVAL '1 year') ORDER BY t.date DESC LIMIT 1;
    SELECT (tot_date_last - INTERVAL '2 years'), t.value INTO tot_date_2years, tot_val_2years FROM BCRA_depositos_efectivo_entidades_financieras_total t WHERE t.date <= (tot_date_last - INTERVAL '2 years') ORDER BY t.date DESC LIMIT 1;
    SELECT (tot_date_last - INTERVAL '3 years'), t.value INTO tot_date_3years, tot_val_3years FROM BCRA_depositos_efectivo_entidades_financieras_total t WHERE t.date <= (tot_date_last - INTERVAL '3 years') ORDER BY t.date DESC LIMIT 1;
    SELECT (tot_date_last - INTERVAL '5 years'), t.value INTO tot_date_5years, tot_val_5years FROM BCRA_depositos_efectivo_entidades_financieras_total t WHERE t.date <= (tot_date_last - INTERVAL '5 years') ORDER BY t.date DESC LIMIT 1;
    SELECT (tot_date_last - INTERVAL '10 years'), t.value INTO tot_date_10years, tot_val_10years FROM BCRA_depositos_efectivo_entidades_financieras_total t WHERE t.date <= (tot_date_last - INTERVAL '10 years') ORDER BY t.date DESC LIMIT 1;

    RETURN NEXT;
END;
$$;


