    SELECT (priv_vis_date_last - INTERVAL '10 years'),t.value INTO priv_vis_date_10years, priv_vis_val_10years FROM bcra_depositos_vista_privado t WHERE t.date <= (priv_vis_date_last - INTERVAL '10 years')ORDER BY t.date DESC LIMIT 1;

