    SELECT (priv_pla_date_last - INTERVAL '2 years'), t.value INTO priv_pla_date_2years,  priv_pla_val_2years  FROM bcra_depositos_plazo_privado t WHERE t.date <= (priv_pla_date_last - INTERVAL '2 years') ORDER BY t.date DESC LIMIT 1;
    SELECT (priv_pla_date_last - INTERVAL '3 years'), t.value INTO priv_pla_date_3years,  priv_pla_val_3years  FROM bcra_depositos_plazo_privado t WHERE t.date <= (priv_pla_date_last - INTERVAL '3 years') ORDER BY t.date DESC LIMIT 1;
    SELECT (priv_pla_date_last - INTERVAL '5 years'), t.value INTO priv_pla_date_5years,  priv_pla_val_5years  FROM bcra_depositos_plazo_privado t WHERE t.date <= (priv_pla_date_last - INTERVAL '5 years') ORDER BY t.date DESC LIMIT 1;
    SELECT (priv_pla_date_last - INTERVAL '10 years'),t.value INTO priv_pla_date_10years, priv_pla_val_10years FROM bcra_depositos_plazo_privado t WHERE t.date <= (priv_pla_date_last - INTERVAL '10 years')ORDER BY t.date DESC LIMIT 1;

    SELECT t.date, t.value INTO pub_tot_date_last, pub_tot_val_last FROM bcra_depositos_publico t ORDER BY t.date DESC LIMIT 1;
    SELECT (pub_tot_date_last - INTERVAL '1 day'),   t.value INTO pub_tot_date_daily,   pub_tot_val_daily   FROM bcra_depositos_publico t WHERE t.date <= (pub_tot_date_last - INTERVAL '1 day')   ORDER BY t.date DESC LIMIT 1;
    SELECT (pub_tot_date_last - INTERVAL '1 month'), t.value INTO pub_tot_date_monthly, pub_tot_val_monthly FROM bcra_depositos_publico t WHERE t.date <= (pub_tot_date_last - INTERVAL '1 month') ORDER BY t.date DESC LIMIT 1;
    SELECT (pub_tot_date_last - INTERVAL '1 year'),  t.value INTO pub_tot_date_yearly,  pub_tot_val_yearly  FROM bcra_depositos_publico t WHERE t.date <= (pub_tot_date_last - INTERVAL '1 year')  ORDER BY t.date DESC LIMIT 1;
    SELECT (pub_tot_date_last - INTERVAL '2 years'), t.value INTO pub_tot_date_2years,  pub_tot_val_2years  FROM bcra_depositos_publico t WHERE t.date <= (pub_tot_date_last - INTERVAL '2 years') ORDER BY t.date DESC LIMIT 1;
    SELECT (pub_tot_date_last - INTERVAL '3 years'), t.value INTO pub_tot_date_3years,  pub_tot_val_3years  FROM bcra_depositos_publico t WHERE t.date <= (pub_tot_date_last - INTERVAL '3 years') ORDER BY t.date DESC LIMIT 1;
    SELECT (pub_tot_date_last - INTERVAL '5 years'), t.value INTO pub_tot_date_5years,  pub_tot_val_5years  FROM bcra_depositos_publico t WHERE t.date <= (pub_tot_date_last - INTERVAL '5 years') ORDER BY t.date DESC LIMIT 1;
    SELECT (pub_tot_date_last - INTERVAL '10 years'),t.value INTO pub_tot_date_10years, pub_tot_val_10years FROM bcra_depositos_publico t WHERE t.date <= (pub_tot_date_last - INTERVAL '10 years')ORDER BY t.date DESC LIMIT 1;

    SELECT t.date, t.value INTO pub_vis_date_last, pub_vis_val_last FROM bcra_depositos_vista_publico t ORDER BY t.date DESC LIMIT 1;
    SELECT (pub_vis_date_last - INTERVAL '1 day'),   t.value INTO pub_vis_date_daily,   pub_vis_val_daily   FROM bcra_depositos_vista_publico t WHERE t.date <= (pub_vis_date_last - INTERVAL '1 day')   ORDER BY t.date DESC LIMIT 1;
    SELECT (pub_vis_date_last - INTERVAL '1 month'), t.value INTO pub_vis_date_monthly, pub_vis_val_monthly FROM bcra_depositos_vista_publico t WHERE t.date <= (pub_vis_date_last - INTERVAL '1 month') ORDER BY t.date DESC LIMIT 1;
    SELECT (pub_vis_date_last - INTERVAL '1 year'),  t.value INTO pub_vis_date_yearly,  pub_vis_val_yearly  FROM bcra_depositos_vista_publico t WHERE t.date <= (pub_vis_date_last - INTERVAL '1 year')  ORDER BY t.date DESC LIMIT 1;
    SELECT (pub_vis_date_last - INTERVAL '2 years'), t.value INTO pub_vis_date_2years,  pub_vis_val_2years  FROM bcra_depositos_vista_publico t WHERE t.date <= (pub_vis_date_last - INTERVAL '2 years') ORDER BY t.date DESC LIMIT 1;
    SELECT (pub_vis_date_last - INTERVAL '3 years'), t.value INTO pub_vis_date_3years,  pub_vis_val_3years  FROM bcra_depositos_vista_publico t WHERE t.date <= (pub_vis_date_last - INTERVAL '3 years') ORDER BY t.date DESC LIMIT 1;
    SELECT (pub_vis_date_last - INTERVAL '5 years'), t.value INTO pub_vis_date_5years,  pub_vis_val_5years  FROM bcra_depositos_vista_publico t WHERE t.date <= (pub_vis_date_last - INTERVAL '5 years') ORDER BY t.date DESC LIMIT 1;
    SELECT (pub_vis_date_last - INTERVAL '10 years'),t.value INTO pub_vis_date_10years, pub_vis_val_10years FROM bcra_depositos_vista_publico t WHERE t.date <= (pub_vis_date_last - INTERVAL '10 years')ORDER BY t.date DESC LIMIT 1;

