    SELECT (pub_pla_date_last - INTERVAL '1 month'), t.value INTO pub_pla_date_monthly, pub_pla_val_monthly FROM bcra_depositos_plazo_publico t WHERE t.date <= (pub_pla_date_last - INTERVAL '1 month') ORDER BY t.date DESC LIMIT 1;
    SELECT (pub_pla_date_last - INTERVAL '1 year'),  t.value INTO pub_pla_date_yearly,  pub_pla_val_yearly  FROM bcra_depositos_plazo_publico t WHERE t.date <= (pub_pla_date_last - INTERVAL '1 year')  ORDER BY t.date DESC LIMIT 1;
    SELECT (pub_pla_date_last - INTERVAL '2 years'), t.value INTO pub_pla_date_2years,  pub_pla_val_2years  FROM bcra_depositos_plazo_publico t WHERE t.date <= (pub_pla_date_last - INTERVAL '2 years') ORDER BY t.date DESC LIMIT 1;
    SELECT (pub_pla_date_last - INTERVAL '3 years'), t.value INTO pub_pla_date_3years,  pub_pla_val_3years  FROM bcra_depositos_plazo_publico t WHERE t.date <= (pub_pla_date_last - INTERVAL '3 years') ORDER BY t.date DESC LIMIT 1;
