-- Name: sp_ebcra_var_depositos_titular(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sp_ebcra_var_depositos_titular() RETURNS TABLE(hum_date_last date, hum_val_last double precision, hum_date_monthly date, hum_val_monthly double precision, hum_date_yearly date, hum_val_yearly double precision, hum_date_2years date, hum_val_2years double precision, hum_date_3years date, hum_val_3years double precision, hum_date_5years date, hum_val_5years double precision, hum_date_10years date, hum_val_10years double precision, jur_date_last date, jur_val_last double precision, jur_date_monthly date, jur_val_monthly double precision, jur_date_yearly date, jur_val_yearly double precision, jur_date_2years date, jur_val_2years double precision, jur_date_3years date, jur_val_3years double precision, jur_date_5years date, jur_val_5years double precision, jur_date_10years date, jur_val_10years double precision, fci_date_last date, fci_val_last double precision, fci_date_monthly date, fci_val_monthly double precision, fci_date_yearly date, fci_val_yearly double precision, fci_date_2years date, fci_val_2years double precision, fci_date_3years date, fci_val_3years double precision, fci_date_5years date, fci_val_5years double precision, fci_date_10years date, fci_val_10years double precision, pymes_date_last date, pymes_val_last double precision, pymes_date_monthly date, pymes_val_monthly double precision, pymes_date_yearly date, pymes_val_yearly double precision, pymes_date_2years date, pymes_val_2years double precision, pymes_date_3years date, pymes_val_3years double precision, pymes_date_5years date, pymes_val_5years double precision, pymes_date_10years date, pymes_val_10years double precision, cc_date_last date, cc_val_last double precision, cc_date_monthly date, cc_val_monthly double precision, cc_date_yearly date, cc_val_yearly double precision, cc_date_2years date, cc_val_2years double precision, cc_date_3years date, cc_val_3years double precision, cc_date_5years date, cc_val_5years double precision, cc_date_10years date, cc_val_10years double precision, ca_date_last date, ca_val_last double precision, ca_date_monthly date, ca_val_monthly double precision, ca_date_yearly date, ca_val_yearly double precision, ca_date_2years date, ca_val_2years double precision, ca_date_3years date, ca_val_3years double precision, ca_date_5years date, ca_val_5years double precision, ca_date_10years date, ca_val_10years double precision, pf_date_last date, pf_val_last double precision, pf_date_monthly date, pf_val_monthly double precision, pf_date_yearly date, pf_val_yearly double precision, pf_date_2years date, pf_val_2years double precision, pf_date_3years date, pf_val_3years double precision, pf_date_5years date, pf_val_5years double precision, pf_date_10years date, pf_val_10years double precision)
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Personas humanas
    SELECT t.date, t.value INTO hum_date_last, hum_val_last FROM bcra_dep_titular_humanas t ORDER BY t.date DESC LIMIT 1;
    SELECT (hum_date_last - INTERVAL '1 month'),  t.value INTO hum_date_monthly,  hum_val_monthly  FROM bcra_dep_titular_humanas t WHERE t.date <= (hum_date_last - INTERVAL '1 month')  ORDER BY t.date DESC LIMIT 1;
    SELECT (hum_date_last - INTERVAL '1 year'),   t.value INTO hum_date_yearly,   hum_val_yearly   FROM bcra_dep_titular_humanas t WHERE t.date <= (hum_date_last - INTERVAL '1 year')   ORDER BY t.date DESC LIMIT 1;
    SELECT (hum_date_last - INTERVAL '2 years'),  t.value INTO hum_date_2years,   hum_val_2years   FROM bcra_dep_titular_humanas t WHERE t.date <= (hum_date_last - INTERVAL '2 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (hum_date_last - INTERVAL '3 years'),  t.value INTO hum_date_3years,   hum_val_3years   FROM bcra_dep_titular_humanas t WHERE t.date <= (hum_date_last - INTERVAL '3 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (hum_date_last - INTERVAL '5 years'),  t.value INTO hum_date_5years,   hum_val_5years   FROM bcra_dep_titular_humanas t WHERE t.date <= (hum_date_last - INTERVAL '5 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (hum_date_last - INTERVAL '10 years'), t.value INTO hum_date_10years,  hum_val_10years  FROM bcra_dep_titular_humanas t WHERE t.date <= (hum_date_last - INTERVAL '10 years') ORDER BY t.date DESC LIMIT 1;

    -- Personas jurídicas
    SELECT t.date, t.value INTO jur_date_last, jur_val_last FROM bcra_dep_titular_juridicas t ORDER BY t.date DESC LIMIT 1;
    SELECT (jur_date_last - INTERVAL '1 month'),  t.value INTO jur_date_monthly,  jur_val_monthly  FROM bcra_dep_titular_juridicas t WHERE t.date <= (jur_date_last - INTERVAL '1 month')  ORDER BY t.date DESC LIMIT 1;
    SELECT (jur_date_last - INTERVAL '1 year'),   t.value INTO jur_date_yearly,   jur_val_yearly   FROM bcra_dep_titular_juridicas t WHERE t.date <= (jur_date_last - INTERVAL '1 year')   ORDER BY t.date DESC LIMIT 1;
    SELECT (jur_date_last - INTERVAL '2 years'),  t.value INTO jur_date_2years,   jur_val_2years   FROM bcra_dep_titular_juridicas t WHERE t.date <= (jur_date_last - INTERVAL '2 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (jur_date_last - INTERVAL '3 years'),  t.value INTO jur_date_3years,   jur_val_3years   FROM bcra_dep_titular_juridicas t WHERE t.date <= (jur_date_last - INTERVAL '3 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (jur_date_last - INTERVAL '5 years'),  t.value INTO jur_date_5years,   jur_val_5years   FROM bcra_dep_titular_juridicas t WHERE t.date <= (jur_date_last - INTERVAL '5 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (jur_date_last - INTERVAL '10 years'), t.value INTO jur_date_10years,  jur_val_10years  FROM bcra_dep_titular_juridicas t WHERE t.date <= (jur_date_last - INTERVAL '10 years') ORDER BY t.date DESC LIMIT 1;

    -- Fondos comunes de inversión
    SELECT t.date, t.value INTO fci_date_last, fci_val_last FROM bcra_dep_titular_fci t ORDER BY t.date DESC LIMIT 1;
    SELECT (fci_date_last - INTERVAL '1 month'),  t.value INTO fci_date_monthly,  fci_val_monthly  FROM bcra_dep_titular_fci t WHERE t.date <= (fci_date_last - INTERVAL '1 month')  ORDER BY t.date DESC LIMIT 1;
    SELECT (fci_date_last - INTERVAL '1 year'),   t.value INTO fci_date_yearly,   fci_val_yearly   FROM bcra_dep_titular_fci t WHERE t.date <= (fci_date_last - INTERVAL '1 year')   ORDER BY t.date DESC LIMIT 1;
    SELECT (fci_date_last - INTERVAL '2 years'),  t.value INTO fci_date_2years,   fci_val_2years   FROM bcra_dep_titular_fci t WHERE t.date <= (fci_date_last - INTERVAL '2 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (fci_date_last - INTERVAL '3 years'),  t.value INTO fci_date_3years,   fci_val_3years   FROM bcra_dep_titular_fci t WHERE t.date <= (fci_date_last - INTERVAL '3 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (fci_date_last - INTERVAL '5 years'),  t.value INTO fci_date_5years,   fci_val_5years   FROM bcra_dep_titular_fci t WHERE t.date <= (fci_date_last - INTERVAL '5 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (fci_date_last - INTERVAL '10 years'), t.value INTO fci_date_10years,  fci_val_10years  FROM bcra_dep_titular_fci t WHERE t.date <= (fci_date_last - INTERVAL '10 years') ORDER BY t.date DESC LIMIT 1;

    -- PyMEs
    SELECT t.date, t.value INTO pymes_date_last, pymes_val_last FROM bcra_dep_titular_pymes t ORDER BY t.date DESC LIMIT 1;
    SELECT (pymes_date_last - INTERVAL '1 month'),  t.value INTO pymes_date_monthly,  pymes_val_monthly  FROM bcra_dep_titular_pymes t WHERE t.date <= (pymes_date_last - INTERVAL '1 month')  ORDER BY t.date DESC LIMIT 1;
    SELECT (pymes_date_last - INTERVAL '1 year'),   t.value INTO pymes_date_yearly,   pymes_val_yearly   FROM bcra_dep_titular_pymes t WHERE t.date <= (pymes_date_last - INTERVAL '1 year')   ORDER BY t.date DESC LIMIT 1;
    SELECT (pymes_date_last - INTERVAL '2 years'),  t.value INTO pymes_date_2years,   pymes_val_2years   FROM bcra_dep_titular_pymes t WHERE t.date <= (pymes_date_last - INTERVAL '2 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (pymes_date_last - INTERVAL '3 years'),  t.value INTO pymes_date_3years,   pymes_val_3years   FROM bcra_dep_titular_pymes t WHERE t.date <= (pymes_date_last - INTERVAL '3 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (pymes_date_last - INTERVAL '5 years'),  t.value INTO pymes_date_5years,   pymes_val_5years   FROM bcra_dep_titular_pymes t WHERE t.date <= (pymes_date_last - INTERVAL '5 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (pymes_date_last - INTERVAL '10 years'), t.value INTO pymes_date_10years,  pymes_val_10years  FROM bcra_dep_titular_pymes t WHERE t.date <= (pymes_date_last - INTERVAL '10 years') ORDER BY t.date DESC LIMIT 1;

    -- Cuentas corrientes del sector privado
    SELECT t.date, t.value INTO cc_date_last, cc_val_last FROM bcra_dep_titular_cc_privado t ORDER BY t.date DESC LIMIT 1;
    SELECT (cc_date_last - INTERVAL '1 month'),  t.value INTO cc_date_monthly,  cc_val_monthly  FROM bcra_dep_titular_cc_privado t WHERE t.date <= (cc_date_last - INTERVAL '1 month')  ORDER BY t.date DESC LIMIT 1;
    SELECT (cc_date_last - INTERVAL '1 year'),   t.value INTO cc_date_yearly,   cc_val_yearly   FROM bcra_dep_titular_cc_privado t WHERE t.date <= (cc_date_last - INTERVAL '1 year')   ORDER BY t.date DESC LIMIT 1;
    SELECT (cc_date_last - INTERVAL '2 years'),  t.value INTO cc_date_2years,   cc_val_2years   FROM bcra_dep_titular_cc_privado t WHERE t.date <= (cc_date_last - INTERVAL '2 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (cc_date_last - INTERVAL '3 years'),  t.value INTO cc_date_3years,   cc_val_3years   FROM bcra_dep_titular_cc_privado t WHERE t.date <= (cc_date_last - INTERVAL '3 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (cc_date_last - INTERVAL '5 years'),  t.value INTO cc_date_5years,   cc_val_5years   FROM bcra_dep_titular_cc_privado t WHERE t.date <= (cc_date_last - INTERVAL '5 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (cc_date_last - INTERVAL '10 years'), t.value INTO cc_date_10years,  cc_val_10years  FROM bcra_dep_titular_cc_privado t WHERE t.date <= (cc_date_last - INTERVAL '10 years') ORDER BY t.date DESC LIMIT 1;

    -- Cajas de ahorro del sector privado
    SELECT t.date, t.value INTO ca_date_last, ca_val_last FROM bcra_dep_titular_ca_privado t ORDER BY t.date DESC LIMIT 1;
    SELECT (ca_date_last - INTERVAL '1 month'),  t.value INTO ca_date_monthly,  ca_val_monthly  FROM bcra_dep_titular_ca_privado t WHERE t.date <= (ca_date_last - INTERVAL '1 month')  ORDER BY t.date DESC LIMIT 1;
    SELECT (ca_date_last - INTERVAL '1 year'),   t.value INTO ca_date_yearly,   ca_val_yearly   FROM bcra_dep_titular_ca_privado t WHERE t.date <= (ca_date_last - INTERVAL '1 year')   ORDER BY t.date DESC LIMIT 1;
    SELECT (ca_date_last - INTERVAL '2 years'),  t.value INTO ca_date_2years,   ca_val_2years   FROM bcra_dep_titular_ca_privado t WHERE t.date <= (ca_date_last - INTERVAL '2 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (ca_date_last - INTERVAL '3 years'),  t.value INTO ca_date_3years,   ca_val_3years   FROM bcra_dep_titular_ca_privado t WHERE t.date <= (ca_date_last - INTERVAL '3 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (ca_date_last - INTERVAL '5 years'),  t.value INTO ca_date_5years,   ca_val_5years   FROM bcra_dep_titular_ca_privado t WHERE t.date <= (ca_date_last - INTERVAL '5 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (ca_date_last - INTERVAL '10 years'), t.value INTO ca_date_10years,  ca_val_10years  FROM bcra_dep_titular_ca_privado t WHERE t.date <= (ca_date_last - INTERVAL '10 years') ORDER BY t.date DESC LIMIT 1;

    -- Plazos fijos del sector privado
    SELECT t.date, t.value INTO pf_date_last, pf_val_last FROM bcra_dep_titular_pf_privado t ORDER BY t.date DESC LIMIT 1;
    SELECT (pf_date_last - INTERVAL '1 month'),  t.value INTO pf_date_monthly,  pf_val_monthly  FROM bcra_dep_titular_pf_privado t WHERE t.date <= (pf_date_last - INTERVAL '1 month')  ORDER BY t.date DESC LIMIT 1;
    SELECT (pf_date_last - INTERVAL '1 year'),   t.value INTO pf_date_yearly,   pf_val_yearly   FROM bcra_dep_titular_pf_privado t WHERE t.date <= (pf_date_last - INTERVAL '1 year')   ORDER BY t.date DESC LIMIT 1;
    SELECT (pf_date_last - INTERVAL '2 years'),  t.value INTO pf_date_2years,   pf_val_2years   FROM bcra_dep_titular_pf_privado t WHERE t.date <= (pf_date_last - INTERVAL '2 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (pf_date_last - INTERVAL '3 years'),  t.value INTO pf_date_3years,   pf_val_3years   FROM bcra_dep_titular_pf_privado t WHERE t.date <= (pf_date_last - INTERVAL '3 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (pf_date_last - INTERVAL '5 years'),  t.value INTO pf_date_5years,   pf_val_5years   FROM bcra_dep_titular_pf_privado t WHERE t.date <= (pf_date_last - INTERVAL '5 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (pf_date_last - INTERVAL '10 years'), t.value INTO pf_date_10years,  pf_val_10years  FROM bcra_dep_titular_pf_privado t WHERE t.date <= (pf_date_last - INTERVAL '10 years') ORDER BY t.date DESC LIMIT 1;

    RETURN NEXT;
END;
$$;


