CREATE FUNCTION public.sp_ebcra_var_depositos_usd() RETURNS TABLE(tot_date_last date, tot_val_last double precision, tot_date_daily date, tot_val_daily double precision, tot_date_monthly date, tot_val_monthly double precision, tot_date_yearly date, tot_val_yearly double precision, tot_date_2years date, tot_val_2years double precision, tot_date_3years date, tot_val_3years double precision, tot_date_5years date, tot_val_5years double precision, tot_date_10years date, tot_val_10years double precision, ef_date_last date, ef_val_last double precision, ef_date_daily date, ef_val_daily double precision, ef_date_monthly date, ef_val_monthly double precision, ef_date_yearly date, ef_val_yearly double precision, ef_date_2years date, ef_val_2years double precision, ef_date_3years date, ef_val_3years double precision, ef_date_5years date, ef_val_5years double precision, ef_date_10years date, ef_val_10years double precision)
    LANGUAGE plpgsql
    AS $$
BEGIN
    SELECT t.date, t.value INTO tot_date_last, tot_val_last FROM bcra_depositos_usd_total t ORDER BY t.date DESC LIMIT 1;
    SELECT (tot_date_last - INTERVAL '1 day'),    t.value INTO tot_date_daily,   tot_val_daily   FROM bcra_depositos_usd_total t WHERE t.date <= (tot_date_last - INTERVAL '1 day')    ORDER BY t.date DESC LIMIT 1;
    SELECT (tot_date_last - INTERVAL '1 month'),  t.value INTO tot_date_monthly, tot_val_monthly FROM bcra_depositos_usd_total t WHERE t.date <= (tot_date_last - INTERVAL '1 month')  ORDER BY t.date DESC LIMIT 1;
    SELECT (tot_date_last - INTERVAL '1 year'),   t.value INTO tot_date_yearly,  tot_val_yearly  FROM bcra_depositos_usd_total t WHERE t.date <= (tot_date_last - INTERVAL '1 year')   ORDER BY t.date DESC LIMIT 1;
    SELECT (tot_date_last - INTERVAL '2 years'),  t.value INTO tot_date_2years,  tot_val_2years  FROM bcra_depositos_usd_total t WHERE t.date <= (tot_date_last - INTERVAL '2 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (tot_date_last - INTERVAL '3 years'),  t.value INTO tot_date_3years,  tot_val_3years  FROM bcra_depositos_usd_total t WHERE t.date <= (tot_date_last - INTERVAL '3 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (tot_date_last - INTERVAL '5 years'),  t.value INTO tot_date_5years,  tot_val_5years  FROM bcra_depositos_usd_total t WHERE t.date <= (tot_date_last - INTERVAL '5 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (tot_date_last - INTERVAL '10 years'), t.value INTO tot_date_10years, tot_val_10years FROM bcra_depositos_usd_total t WHERE t.date <= (tot_date_last - INTERVAL '10 years') ORDER BY t.date DESC LIMIT 1;

    SELECT t.date, t.value INTO ef_date_last, ef_val_last FROM bcra_depositos_usd_efectivo t ORDER BY t.date DESC LIMIT 1;
    SELECT (ef_date_last - INTERVAL '1 day'),    t.value INTO ef_date_daily,   ef_val_daily   FROM bcra_depositos_usd_efectivo t WHERE t.date <= (ef_date_last - INTERVAL '1 day')    ORDER BY t.date DESC LIMIT 1;
    SELECT (ef_date_last - INTERVAL '1 month'),  t.value INTO ef_date_monthly, ef_val_monthly FROM bcra_depositos_usd_efectivo t WHERE t.date <= (ef_date_last - INTERVAL '1 month')  ORDER BY t.date DESC LIMIT 1;
    SELECT (ef_date_last - INTERVAL '1 year'),   t.value INTO ef_date_yearly,  ef_val_yearly  FROM bcra_depositos_usd_efectivo t WHERE t.date <= (ef_date_last - INTERVAL '1 year')   ORDER BY t.date DESC LIMIT 1;
    SELECT (ef_date_last - INTERVAL '2 years'),  t.value INTO ef_date_2years,  ef_val_2years  FROM bcra_depositos_usd_efectivo t WHERE t.date <= (ef_date_last - INTERVAL '2 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (ef_date_last - INTERVAL '3 years'),  t.value INTO ef_date_3years,  ef_val_3years  FROM bcra_depositos_usd_efectivo t WHERE t.date <= (ef_date_last - INTERVAL '3 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (ef_date_last - INTERVAL '5 years'),  t.value INTO ef_date_5years,  ef_val_5years  FROM bcra_depositos_usd_efectivo t WHERE t.date <= (ef_date_last - INTERVAL '5 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (ef_date_last - INTERVAL '10 years'), t.value INTO ef_date_10years, ef_val_10years FROM bcra_depositos_usd_efectivo t WHERE t.date <= (ef_date_last - INTERVAL '10 years') ORDER BY t.date DESC LIMIT 1;

    RETURN NEXT;
END;
$$;


