CREATE FUNCTION public.sp_ebcra_var_hipotecarios_prendarios() RETURNS TABLE(hip_nueva_date_last date, hip_nueva_val_last double precision, hip_nueva_date_monthly date, hip_nueva_val_monthly double precision, hip_nueva_date_yearly date, hip_nueva_val_yearly double precision, hip_nueva_date_2years date, hip_nueva_val_2years double precision, hip_nueva_date_3years date, hip_nueva_val_3years double precision, hip_nueva_date_5years date, hip_nueva_val_5years double precision, hip_nueva_date_10years date, hip_nueva_val_10years double precision, hip_usada_date_last date, hip_usada_val_last double precision, hip_usada_date_monthly date, hip_usada_val_monthly double precision, hip_usada_date_yearly date, hip_usada_val_yearly double precision, hip_usada_date_2years date, hip_usada_val_2years double precision, hip_usada_date_3years date, hip_usada_val_3years double precision, hip_usada_date_5years date, hip_usada_val_5years double precision, hip_usada_date_10years date, hip_usada_val_10years double precision, hip_cons_date_last date, hip_cons_val_last double precision, hip_cons_date_monthly date, hip_cons_val_monthly double precision, hip_cons_date_yearly date, hip_cons_val_yearly double precision, hip_cons_date_2years date, hip_cons_val_2years double precision, hip_cons_date_3years date, hip_cons_val_3years double precision, hip_cons_date_5years date, hip_cons_val_5years double precision, hip_cons_date_10years date, hip_cons_val_10years double precision, hip_ref_date_last date, hip_ref_val_last double precision, hip_ref_date_monthly date, hip_ref_val_monthly double precision, hip_ref_date_yearly date, hip_ref_val_yearly double precision, hip_ref_date_2years date, hip_ref_val_2years double precision, hip_ref_date_3years date, hip_ref_val_3years double precision, hip_ref_date_5years date, hip_ref_val_5years double precision, hip_ref_date_10years date, hip_ref_val_10years double precision, hip_otros_date_last date, hip_otros_val_last double precision, hip_otros_date_monthly date, hip_otros_val_monthly double precision, hip_otros_date_yearly date, hip_otros_val_yearly double precision, hip_otros_date_2years date, hip_otros_val_2years double precision, hip_otros_date_3years date, hip_otros_val_3years double precision, hip_otros_date_5years date, hip_otros_val_5years double precision, hip_otros_date_10years date, hip_otros_val_10years double precision, prend_autos_date_last date, prend_autos_val_last double precision, prend_autos_date_monthly date, prend_autos_val_monthly double precision, prend_autos_date_yearly date, prend_autos_val_yearly double precision, prend_autos_date_2years date, prend_autos_val_2years double precision, prend_autos_date_3years date, prend_autos_val_3years double precision, prend_autos_date_5years date, prend_autos_val_5years double precision, prend_autos_date_10years date, prend_autos_val_10years double precision, prend_maq_date_last date, prend_maq_val_last double precision, prend_maq_date_monthly date, prend_maq_val_monthly double precision, prend_maq_date_yearly date, prend_maq_val_yearly double precision, prend_maq_date_2years date, prend_maq_val_2years double precision, prend_maq_date_3years date, prend_maq_val_3years double precision, prend_maq_date_5years date, prend_maq_val_5years double precision, prend_maq_date_10years date, prend_maq_val_10years double precision, prend_otros_date_last date, prend_otros_val_last double precision, prend_otros_date_monthly date, prend_otros_val_monthly double precision, prend_otros_date_yearly date, prend_otros_val_yearly double precision, prend_otros_date_2years date, prend_otros_val_2years double precision, prend_otros_date_3years date, prend_otros_val_3years double precision, prend_otros_date_5years date, prend_otros_val_5years double precision, prend_otros_date_10years date, prend_otros_val_10years double precision)
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Hipotecarios viviendas nuevas
    SELECT t.date, t.value INTO hip_nueva_date_last, hip_nueva_val_last FROM bcra_hip_nueva t ORDER BY t.date DESC LIMIT 1;
    SELECT (hip_nueva_date_last - INTERVAL '1 month'),  t.value INTO hip_nueva_date_monthly,  hip_nueva_val_monthly  FROM bcra_hip_nueva t WHERE t.date <= (hip_nueva_date_last - INTERVAL '1 month')  ORDER BY t.date DESC LIMIT 1;
    SELECT (hip_nueva_date_last - INTERVAL '1 year'),   t.value INTO hip_nueva_date_yearly,   hip_nueva_val_yearly   FROM bcra_hip_nueva t WHERE t.date <= (hip_nueva_date_last - INTERVAL '1 year')   ORDER BY t.date DESC LIMIT 1;
    SELECT (hip_nueva_date_last - INTERVAL '2 years'),  t.value INTO hip_nueva_date_2years,   hip_nueva_val_2years   FROM bcra_hip_nueva t WHERE t.date <= (hip_nueva_date_last - INTERVAL '2 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (hip_nueva_date_last - INTERVAL '3 years'),  t.value INTO hip_nueva_date_3years,   hip_nueva_val_3years   FROM bcra_hip_nueva t WHERE t.date <= (hip_nueva_date_last - INTERVAL '3 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (hip_nueva_date_last - INTERVAL '5 years'),  t.value INTO hip_nueva_date_5years,   hip_nueva_val_5years   FROM bcra_hip_nueva t WHERE t.date <= (hip_nueva_date_last - INTERVAL '5 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (hip_nueva_date_last - INTERVAL '10 years'), t.value INTO hip_nueva_date_10years,  hip_nueva_val_10years  FROM bcra_hip_nueva t WHERE t.date <= (hip_nueva_date_last - INTERVAL '10 years') ORDER BY t.date DESC LIMIT 1;

    -- Hipotecarios viviendas usadas
    SELECT t.date, t.value INTO hip_usada_date_last, hip_usada_val_last FROM bcra_hip_usada t ORDER BY t.date DESC LIMIT 1;
    SELECT (hip_usada_date_last - INTERVAL '1 month'),  t.value INTO hip_usada_date_monthly,  hip_usada_val_monthly  FROM bcra_hip_usada t WHERE t.date <= (hip_usada_date_last - INTERVAL '1 month')  ORDER BY t.date DESC LIMIT 1;
    SELECT (hip_usada_date_last - INTERVAL '1 year'),   t.value INTO hip_usada_date_yearly,   hip_usada_val_yearly   FROM bcra_hip_usada t WHERE t.date <= (hip_usada_date_last - INTERVAL '1 year')   ORDER BY t.date DESC LIMIT 1;
    SELECT (hip_usada_date_last - INTERVAL '2 years'),  t.value INTO hip_usada_date_2years,   hip_usada_val_2years   FROM bcra_hip_usada t WHERE t.date <= (hip_usada_date_last - INTERVAL '2 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (hip_usada_date_last - INTERVAL '3 years'),  t.value INTO hip_usada_date_3years,   hip_usada_val_3years   FROM bcra_hip_usada t WHERE t.date <= (hip_usada_date_last - INTERVAL '3 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (hip_usada_date_last - INTERVAL '5 years'),  t.value INTO hip_usada_date_5years,   hip_usada_val_5years   FROM bcra_hip_usada t WHERE t.date <= (hip_usada_date_last - INTERVAL '5 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (hip_usada_date_last - INTERVAL '10 years'), t.value INTO hip_usada_date_10years,  hip_usada_val_10years  FROM bcra_hip_usada t WHERE t.date <= (hip_usada_date_last - INTERVAL '10 years') ORDER BY t.date DESC LIMIT 1;

    -- Hipotecarios construcción
    SELECT t.date, t.value INTO hip_cons_date_last, hip_cons_val_last FROM bcra_hip_construccion t ORDER BY t.date DESC LIMIT 1;
    SELECT (hip_cons_date_last - INTERVAL '1 month'),  t.value INTO hip_cons_date_monthly,  hip_cons_val_monthly  FROM bcra_hip_construccion t WHERE t.date <= (hip_cons_date_last - INTERVAL '1 month')  ORDER BY t.date DESC LIMIT 1;
    SELECT (hip_cons_date_last - INTERVAL '1 year'),   t.value INTO hip_cons_date_yearly,   hip_cons_val_yearly   FROM bcra_hip_construccion t WHERE t.date <= (hip_cons_date_last - INTERVAL '1 year')   ORDER BY t.date DESC LIMIT 1;
    SELECT (hip_cons_date_last - INTERVAL '2 years'),  t.value INTO hip_cons_date_2years,   hip_cons_val_2years   FROM bcra_hip_construccion t WHERE t.date <= (hip_cons_date_last - INTERVAL '2 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (hip_cons_date_last - INTERVAL '3 years'),  t.value INTO hip_cons_date_3years,   hip_cons_val_3years   FROM bcra_hip_construccion t WHERE t.date <= (hip_cons_date_last - INTERVAL '3 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (hip_cons_date_last - INTERVAL '5 years'),  t.value INTO hip_cons_date_5years,   hip_cons_val_5years   FROM bcra_hip_construccion t WHERE t.date <= (hip_cons_date_last - INTERVAL '5 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (hip_cons_date_last - INTERVAL '10 years'), t.value INTO hip_cons_date_10years,  hip_cons_val_10years  FROM bcra_hip_construccion t WHERE t.date <= (hip_cons_date_last - INTERVAL '10 years') ORDER BY t.date DESC LIMIT 1;

    -- Hipotecarios refacción
    SELECT t.date, t.value INTO hip_ref_date_last, hip_ref_val_last FROM bcra_hip_refaccion t ORDER BY t.date DESC LIMIT 1;
    SELECT (hip_ref_date_last - INTERVAL '1 month'),  t.value INTO hip_ref_date_monthly,  hip_ref_val_monthly  FROM bcra_hip_refaccion t WHERE t.date <= (hip_ref_date_last - INTERVAL '1 month')  ORDER BY t.date DESC LIMIT 1;
    SELECT (hip_ref_date_last - INTERVAL '1 year'),   t.value INTO hip_ref_date_yearly,   hip_ref_val_yearly   FROM bcra_hip_refaccion t WHERE t.date <= (hip_ref_date_last - INTERVAL '1 year')   ORDER BY t.date DESC LIMIT 1;
    SELECT (hip_ref_date_last - INTERVAL '2 years'),  t.value INTO hip_ref_date_2years,   hip_ref_val_2years   FROM bcra_hip_refaccion t WHERE t.date <= (hip_ref_date_last - INTERVAL '2 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (hip_ref_date_last - INTERVAL '3 years'),  t.value INTO hip_ref_date_3years,   hip_ref_val_3years   FROM bcra_hip_refaccion t WHERE t.date <= (hip_ref_date_last - INTERVAL '3 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (hip_ref_date_last - INTERVAL '5 years'),  t.value INTO hip_ref_date_5years,   hip_ref_val_5years   FROM bcra_hip_refaccion t WHERE t.date <= (hip_ref_date_last - INTERVAL '5 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (hip_ref_date_last - INTERVAL '10 years'), t.value INTO hip_ref_date_10years,  hip_ref_val_10years  FROM bcra_hip_refaccion t WHERE t.date <= (hip_ref_date_last - INTERVAL '10 years') ORDER BY t.date DESC LIMIT 1;

    -- Hipotecarios otros
    SELECT t.date, t.value INTO hip_otros_date_last, hip_otros_val_last FROM bcra_hip_otros t ORDER BY t.date DESC LIMIT 1;
    SELECT (hip_otros_date_last - INTERVAL '1 month'),  t.value INTO hip_otros_date_monthly,  hip_otros_val_monthly  FROM bcra_hip_otros t WHERE t.date <= (hip_otros_date_last - INTERVAL '1 month')  ORDER BY t.date DESC LIMIT 1;
    SELECT (hip_otros_date_last - INTERVAL '1 year'),   t.value INTO hip_otros_date_yearly,   hip_otros_val_yearly   FROM bcra_hip_otros t WHERE t.date <= (hip_otros_date_last - INTERVAL '1 year')   ORDER BY t.date DESC LIMIT 1;
    SELECT (hip_otros_date_last - INTERVAL '2 years'),  t.value INTO hip_otros_date_2years,   hip_otros_val_2years   FROM bcra_hip_otros t WHERE t.date <= (hip_otros_date_last - INTERVAL '2 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (hip_otros_date_last - INTERVAL '3 years'),  t.value INTO hip_otros_date_3years,   hip_otros_val_3years   FROM bcra_hip_otros t WHERE t.date <= (hip_otros_date_last - INTERVAL '3 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (hip_otros_date_last - INTERVAL '5 years'),  t.value INTO hip_otros_date_5years,   hip_otros_val_5years   FROM bcra_hip_otros t WHERE t.date <= (hip_otros_date_last - INTERVAL '5 years')  ORDER BY t.date DESC LIMIT 1;
