--

CREATE FUNCTION public.sp_ebcra_var_m3() RETURNS TABLE(m3_date_last date, m3_val_last double precision, m3_date_daily date, m3_val_daily double precision, m3_date_monthly date, m3_val_monthly double precision, m3_date_yearly date, m3_val_yearly double precision, m3_date_2years date, m3_val_2years double precision, m3_date_3years date, m3_val_3years double precision, m3_date_5years date, m3_val_5years double precision, m3_date_10years date, m3_val_10years double precision)
    LANGUAGE plpgsql
    AS $$
BEGIN
    SELECT t.date, t.value INTO m3_date_last, m3_val_last FROM bcra_m3 t ORDER BY t.date DESC LIMIT 1;
    SELECT (m3_date_last - INTERVAL '1 day'), t.value INTO m3_date_daily, m3_val_daily FROM bcra_m3 t WHERE t.date <= (m3_date_last - INTERVAL '1 day') ORDER BY t.date DESC LIMIT 1;
    SELECT (m3_date_last - INTERVAL '1 month'), t.value INTO m3_date_monthly, m3_val_monthly FROM bcra_m3 t WHERE t.date <= (m3_date_last - INTERVAL '1 month') ORDER BY t.date DESC LIMIT 1;
    SELECT (m3_date_last - INTERVAL '1 year'), t.value INTO m3_date_yearly, m3_val_yearly FROM bcra_m3 t WHERE t.date <= (m3_date_last - INTERVAL '1 year') ORDER BY t.date DESC LIMIT 1;
    SELECT (m3_date_last - INTERVAL '2 years'), t.value INTO m3_date_2years, m3_val_2years FROM bcra_m3 t WHERE t.date <= (m3_date_last - INTERVAL '2 years') ORDER BY t.date DESC LIMIT 1;
    SELECT (m3_date_last - INTERVAL '3 years'), t.value INTO m3_date_3years, m3_val_3years FROM bcra_m3 t WHERE t.date <= (m3_date_last - INTERVAL '3 years') ORDER BY t.date DESC LIMIT 1;
    SELECT (m3_date_last - INTERVAL '5 years'), t.value INTO m3_date_5years, m3_val_5years FROM bcra_m3 t WHERE t.date <= (m3_date_last - INTERVAL '5 years') ORDER BY t.date DESC LIMIT 1;
    SELECT (m3_date_last - INTERVAL '10 years'), t.value INTO m3_date_10years, m3_val_10years FROM bcra_m3 t WHERE t.date <= (m3_date_last - INTERVAL '10 years') ORDER BY t.date DESC LIMIT 1;
    RETURN NEXT;
END;
$$;


