    SELECT (pt_date_last - INTERVAL '5 years'), t.value INTO pt_date_5years,  pt_val_5years  FROM bcra_prestamos_personales_tarjetas t WHERE t.date <= (pt_date_last - INTERVAL '5 years') ORDER BY t.date DESC LIMIT 1;
    SELECT (pt_date_last - INTERVAL '10 years'),t.value INTO pt_date_10years, pt_val_10years FROM bcra_prestamos_personales_tarjetas t WHERE t.date <= (pt_date_last - INTERVAL '10 years')ORDER BY t.date DESC LIMIT 1;

    SELECT t.date, t.value INTO hp_date_last, hp_val_last FROM bcra_prestamos_hipotecarios_prendarios t ORDER BY t.date DESC LIMIT 1;
    SELECT (hp_date_last - INTERVAL '1 day'),   t.value INTO hp_date_daily,   hp_val_daily   FROM bcra_prestamos_hipotecarios_prendarios t WHERE t.date <= (hp_date_last - INTERVAL '1 day')   ORDER BY t.date DESC LIMIT 1;
    SELECT (hp_date_last - INTERVAL '1 month'), t.value INTO hp_date_monthly, hp_val_monthly FROM bcra_prestamos_hipotecarios_prendarios t WHERE t.date <= (hp_date_last - INTERVAL '1 month') ORDER BY t.date DESC LIMIT 1;
    SELECT (hp_date_last - INTERVAL '1 year'),  t.value INTO hp_date_yearly,  hp_val_yearly  FROM bcra_prestamos_hipotecarios_prendarios t WHERE t.date <= (hp_date_last - INTERVAL '1 year')  ORDER BY t.date DESC LIMIT 1;
    SELECT (hp_date_last - INTERVAL '2 years'), t.value INTO hp_date_2years,  hp_val_2years  FROM bcra_prestamos_hipotecarios_prendarios t WHERE t.date <= (hp_date_last - INTERVAL '2 years') ORDER BY t.date DESC LIMIT 1;
    SELECT (hp_date_last - INTERVAL '3 years'), t.value INTO hp_date_3years,  hp_val_3years  FROM bcra_prestamos_hipotecarios_prendarios t WHERE t.date <= (hp_date_last - INTERVAL '3 years') ORDER BY t.date DESC LIMIT 1;
    SELECT (hp_date_last - INTERVAL '5 years'), t.value INTO hp_date_5years,  hp_val_5years  FROM bcra_prestamos_hipotecarios_prendarios t WHERE t.date <= (hp_date_last - INTERVAL '5 years') ORDER BY t.date DESC LIMIT 1;
    SELECT (hp_date_last - INTERVAL '10 years'),t.value INTO hp_date_10years, hp_val_10years FROM bcra_prestamos_hipotecarios_prendarios t WHERE t.date <= (hp_date_last - INTERVAL '10 years')ORDER BY t.date DESC LIMIT 1;

    SELECT t.date, t.value INTO ot_date_last, ot_val_last FROM bcra_prestamos_otros t ORDER BY t.date DESC LIMIT 1;
    SELECT (ot_date_last - INTERVAL '1 day'),   t.value INTO ot_date_daily,   ot_val_daily   FROM bcra_prestamos_otros t WHERE t.date <= (ot_date_last - INTERVAL '1 day')   ORDER BY t.date DESC LIMIT 1;
    SELECT (ot_date_last - INTERVAL '1 month'), t.value INTO ot_date_monthly, ot_val_monthly FROM bcra_prestamos_otros t WHERE t.date <= (ot_date_last - INTERVAL '1 month') ORDER BY t.date DESC LIMIT 1;
    SELECT (ot_date_last - INTERVAL '1 year'),  t.value INTO ot_date_yearly,  ot_val_yearly  FROM bcra_prestamos_otros t WHERE t.date <= (ot_date_last - INTERVAL '1 year')  ORDER BY t.date DESC LIMIT 1;
    SELECT (ot_date_last - INTERVAL '2 years'), t.value INTO ot_date_2years,  ot_val_2years  FROM bcra_prestamos_otros t WHERE t.date <= (ot_date_last - INTERVAL '2 years') ORDER BY t.date DESC LIMIT 1;
    SELECT (ot_date_last - INTERVAL '3 years'), t.value INTO ot_date_3years,  ot_val_3years  FROM bcra_prestamos_otros t WHERE t.date <= (ot_date_last - INTERVAL '3 years') ORDER BY t.date DESC LIMIT 1;
    SELECT (ot_date_last - INTERVAL '5 years'), t.value INTO ot_date_5years,  ot_val_5years  FROM bcra_prestamos_otros t WHERE t.date <= (ot_date_last - INTERVAL '5 years') ORDER BY t.date DESC LIMIT 1;
    SELECT (ot_date_last - INTERVAL '10 years'),t.value INTO ot_date_10years, ot_val_10years FROM bcra_prestamos_otros t WHERE t.date <= (ot_date_last - INTERVAL '10 years')ORDER BY t.date DESC LIMIT 1;

    RETURN NEXT;
END;
$$;


