--
-- Name: sp_ebcra_var_prestamos_titular(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sp_ebcra_var_prestamos_titular() RETURNS TABLE(tot_date_last date, tot_val_last double precision, tot_date_monthly date, tot_val_monthly double precision, tot_date_yearly date, tot_val_yearly double precision, tot_date_2years date, tot_val_2years double precision, tot_date_3years date, tot_val_3years double precision, tot_date_5years date, tot_val_5years double precision, tot_date_10years date, tot_val_10years double precision, hum_date_last date, hum_val_last double precision, hum_date_monthly date, hum_val_monthly double precision, hum_date_yearly date, hum_val_yearly double precision, hum_date_2years date, hum_val_2years double precision, hum_date_3years date, hum_val_3years double precision, hum_date_5years date, hum_val_5years double precision, hum_date_10years date, hum_val_10years double precision, jur_date_last date, jur_val_last double precision, jur_date_monthly date, jur_val_monthly double precision, jur_date_yearly date, jur_val_yearly double precision, jur_date_2years date, jur_val_2years double precision, jur_date_3years date, jur_val_3years double precision, jur_date_5years date, jur_val_5years double precision, jur_date_10years date, jur_val_10years double precision, pym_date_last date, pym_val_last double precision, pym_date_monthly date, pym_val_monthly double precision, pym_date_yearly date, pym_val_yearly double precision, pym_date_2years date, pym_val_2years double precision, pym_date_3years date, pym_val_3years double precision, pym_date_5years date, pym_val_5years double precision, pym_date_10years date, pym_val_10years double precision, hip_date_last date, hip_val_last double precision, hip_date_monthly date, hip_val_monthly double precision, hip_date_yearly date, hip_val_yearly double precision, hip_date_2years date, hip_val_2years double precision, hip_date_3years date, hip_val_3years double precision, hip_date_5years date, hip_val_5years double precision, hip_date_10years date, hip_val_10years double precision, prend_date_last date, prend_val_last double precision, prend_date_monthly date, prend_val_monthly double precision, prend_date_yearly date, prend_val_yearly double precision, prend_date_2years date, prend_val_2years double precision, prend_date_3years date, prend_val_3years double precision, prend_date_5years date, prend_val_5years double precision, prend_date_10years date, prend_val_10years double precision)
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Total sector privado no financiero
    SELECT t.date, t.value INTO tot_date_last, tot_val_last FROM bcra_prest_titular_privado_total t ORDER BY t.date DESC LIMIT 1;
    SELECT (tot_date_last - INTERVAL '1 month'),  t.value INTO tot_date_monthly,  tot_val_monthly  FROM bcra_prest_titular_privado_total t WHERE t.date <= (tot_date_last - INTERVAL '1 month')  ORDER BY t.date DESC LIMIT 1;
    SELECT (tot_date_last - INTERVAL '1 year'),   t.value INTO tot_date_yearly,   tot_val_yearly   FROM bcra_prest_titular_privado_total t WHERE t.date <= (tot_date_last - INTERVAL '1 year')   ORDER BY t.date DESC LIMIT 1;
    SELECT (tot_date_last - INTERVAL '2 years'),  t.value INTO tot_date_2years,   tot_val_2years   FROM bcra_prest_titular_privado_total t WHERE t.date <= (tot_date_last - INTERVAL '2 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (tot_date_last - INTERVAL '3 years'),  t.value INTO tot_date_3years,   tot_val_3years   FROM bcra_prest_titular_privado_total t WHERE t.date <= (tot_date_last - INTERVAL '3 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (tot_date_last - INTERVAL '5 years'),  t.value INTO tot_date_5years,   tot_val_5years   FROM bcra_prest_titular_privado_total t WHERE t.date <= (tot_date_last - INTERVAL '5 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (tot_date_last - INTERVAL '10 years'), t.value INTO tot_date_10years,  tot_val_10years  FROM bcra_prest_titular_privado_total t WHERE t.date <= (tot_date_last - INTERVAL '10 years') ORDER BY t.date DESC LIMIT 1;

    -- Personas humanas
    SELECT t.date, t.value INTO hum_date_last, hum_val_last FROM bcra_prest_titular_humanas t ORDER BY t.date DESC LIMIT 1;
    SELECT (hum_date_last - INTERVAL '1 month'),  t.value INTO hum_date_monthly,  hum_val_monthly  FROM bcra_prest_titular_humanas t WHERE t.date <= (hum_date_last - INTERVAL '1 month')  ORDER BY t.date DESC LIMIT 1;
    SELECT (hum_date_last - INTERVAL '1 year'),   t.value INTO hum_date_yearly,   hum_val_yearly   FROM bcra_prest_titular_humanas t WHERE t.date <= (hum_date_last - INTERVAL '1 year')   ORDER BY t.date DESC LIMIT 1;
    SELECT (hum_date_last - INTERVAL '2 years'),  t.value INTO hum_date_2years,   hum_val_2years   FROM bcra_prest_titular_humanas t WHERE t.date <= (hum_date_last - INTERVAL '2 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (hum_date_last - INTERVAL '3 years'),  t.value INTO hum_date_3years,   hum_val_3years   FROM bcra_prest_titular_humanas t WHERE t.date <= (hum_date_last - INTERVAL '3 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (hum_date_last - INTERVAL '5 years'),  t.value INTO hum_date_5years,   hum_val_5years   FROM bcra_prest_titular_humanas t WHERE t.date <= (hum_date_last - INTERVAL '5 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (hum_date_last - INTERVAL '10 years'), t.value INTO hum_date_10years,  hum_val_10years  FROM bcra_prest_titular_humanas t WHERE t.date <= (hum_date_last - INTERVAL '10 years') ORDER BY t.date DESC LIMIT 1;

    -- Personas jurídicas
    SELECT t.date, t.value INTO jur_date_last, jur_val_last FROM bcra_prest_titular_juridicas t ORDER BY t.date DESC LIMIT 1;
    SELECT (jur_date_last - INTERVAL '1 month'),  t.value INTO jur_date_monthly,  jur_val_monthly  FROM bcra_prest_titular_juridicas t WHERE t.date <= (jur_date_last - INTERVAL '1 month')  ORDER BY t.date DESC LIMIT 1;
    SELECT (jur_date_last - INTERVAL '1 year'),   t.value INTO jur_date_yearly,   jur_val_yearly   FROM bcra_prest_titular_juridicas t WHERE t.date <= (jur_date_last - INTERVAL '1 year')   ORDER BY t.date DESC LIMIT 1;
    SELECT (jur_date_last - INTERVAL '2 years'),  t.value INTO jur_date_2years,   jur_val_2years   FROM bcra_prest_titular_juridicas t WHERE t.date <= (jur_date_last - INTERVAL '2 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (jur_date_last - INTERVAL '3 years'),  t.value INTO jur_date_3years,   jur_val_3years   FROM bcra_prest_titular_juridicas t WHERE t.date <= (jur_date_last - INTERVAL '3 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (jur_date_last - INTERVAL '5 years'),  t.value INTO jur_date_5years,   jur_val_5years   FROM bcra_prest_titular_juridicas t WHERE t.date <= (jur_date_last - INTERVAL '5 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (jur_date_last - INTERVAL '10 years'), t.value INTO jur_date_10years,  jur_val_10years  FROM bcra_prest_titular_juridicas t WHERE t.date <= (jur_date_last - INTERVAL '10 years') ORDER BY t.date DESC LIMIT 1;

    -- PyMEs
    SELECT t.date, t.value INTO pym_date_last, pym_val_last FROM bcra_prest_titular_pymes t ORDER BY t.date DESC LIMIT 1;
    SELECT (pym_date_last - INTERVAL '1 month'),  t.value INTO pym_date_monthly,  pym_val_monthly  FROM bcra_prest_titular_pymes t WHERE t.date <= (pym_date_last - INTERVAL '1 month')  ORDER BY t.date DESC LIMIT 1;
    SELECT (pym_date_last - INTERVAL '1 year'),   t.value INTO pym_date_yearly,   pym_val_yearly   FROM bcra_prest_titular_pymes t WHERE t.date <= (pym_date_last - INTERVAL '1 year')   ORDER BY t.date DESC LIMIT 1;
    SELECT (pym_date_last - INTERVAL '2 years'),  t.value INTO pym_date_2years,   pym_val_2years   FROM bcra_prest_titular_pymes t WHERE t.date <= (pym_date_last - INTERVAL '2 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (pym_date_last - INTERVAL '3 years'),  t.value INTO pym_date_3years,   pym_val_3years   FROM bcra_prest_titular_pymes t WHERE t.date <= (pym_date_last - INTERVAL '3 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (pym_date_last - INTERVAL '5 years'),  t.value INTO pym_date_5years,   pym_val_5years   FROM bcra_prest_titular_pymes t WHERE t.date <= (pym_date_last - INTERVAL '5 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (pym_date_last - INTERVAL '10 years'), t.value INTO pym_date_10years,  pym_val_10years  FROM bcra_prest_titular_pymes t WHERE t.date <= (pym_date_last - INTERVAL '10 years') ORDER BY t.date DESC LIMIT 1;

    -- Hipotecarios
    SELECT t.date, t.value INTO hip_date_last, hip_val_last FROM bcra_prest_titular_hipotecarios t ORDER BY t.date DESC LIMIT 1;
    SELECT (hip_date_last - INTERVAL '1 month'),  t.value INTO hip_date_monthly,  hip_val_monthly  FROM bcra_prest_titular_hipotecarios t WHERE t.date <= (hip_date_last - INTERVAL '1 month')  ORDER BY t.date DESC LIMIT 1;
    SELECT (hip_date_last - INTERVAL '1 year'),   t.value INTO hip_date_yearly,   hip_val_yearly   FROM bcra_prest_titular_hipotecarios t WHERE t.date <= (hip_date_last - INTERVAL '1 year')   ORDER BY t.date DESC LIMIT 1;
    SELECT (hip_date_last - INTERVAL '2 years'),  t.value INTO hip_date_2years,   hip_val_2years   FROM bcra_prest_titular_hipotecarios t WHERE t.date <= (hip_date_last - INTERVAL '2 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (hip_date_last - INTERVAL '3 years'),  t.value INTO hip_date_3years,   hip_val_3years   FROM bcra_prest_titular_hipotecarios t WHERE t.date <= (hip_date_last - INTERVAL '3 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (hip_date_last - INTERVAL '5 years'),  t.value INTO hip_date_5years,   hip_val_5years   FROM bcra_prest_titular_hipotecarios t WHERE t.date <= (hip_date_last - INTERVAL '5 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (hip_date_last - INTERVAL '10 years'), t.value INTO hip_date_10years,  hip_val_10years  FROM bcra_prest_titular_hipotecarios t WHERE t.date <= (hip_date_last - INTERVAL '10 years') ORDER BY t.date DESC LIMIT 1;

    -- Prendarios
    SELECT t.date, t.value INTO prend_date_last, prend_val_last FROM bcra_prest_titular_prendarios t ORDER BY t.date DESC LIMIT 1;
    SELECT (prend_date_last - INTERVAL '1 month'),  t.value INTO prend_date_monthly,  prend_val_monthly  FROM bcra_prest_titular_prendarios t WHERE t.date <= (prend_date_last - INTERVAL '1 month')  ORDER BY t.date DESC LIMIT 1;
    SELECT (prend_date_last - INTERVAL '1 year'),   t.value INTO prend_date_yearly,   prend_val_yearly   FROM bcra_prest_titular_prendarios t WHERE t.date <= (prend_date_last - INTERVAL '1 year')   ORDER BY t.date DESC LIMIT 1;
    SELECT (prend_date_last - INTERVAL '2 years'),  t.value INTO prend_date_2years,   prend_val_2years   FROM bcra_prest_titular_prendarios t WHERE t.date <= (prend_date_last - INTERVAL '2 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (prend_date_last - INTERVAL '3 years'),  t.value INTO prend_date_3years,   prend_val_3years   FROM bcra_prest_titular_prendarios t WHERE t.date <= (prend_date_last - INTERVAL '3 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (prend_date_last - INTERVAL '5 years'),  t.value INTO prend_date_5years,   prend_val_5years   FROM bcra_prest_titular_prendarios t WHERE t.date <= (prend_date_last - INTERVAL '5 years')  ORDER BY t.date DESC LIMIT 1;
    SELECT (prend_date_last - INTERVAL '10 years'), t.value INTO prend_date_10years,  prend_val_10years  FROM bcra_prest_titular_prendarios t WHERE t.date <= (prend_date_last - INTERVAL '10 years') ORDER BY t.date DESC LIMIT 1;

    RETURN NEXT;
END;
$$;


