--
-- Name: sp_ebcra_var_res(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sp_ebcra_var_res() RETURNS TABLE(res_date_last date, res_val_last double precision, res_date_daily date, res_val_daily double precision, res_date_monthly date, res_val_monthly double precision, res_date_yearly date, res_val_yearly double precision, res_date_2years date, res_val_2years double precision, res_date_3years date, res_val_3years double precision, res_date_5years date, res_val_5years double precision, res_date_10years date, res_val_10years double precision)
    LANGUAGE plpgsql
    AS $$
BEGIN
    SELECT t.date, t.value INTO res_date_last, res_val_last FROM BCRA_reservas_internacionales t ORDER BY t.date DESC LIMIT 1;
    SELECT (res_date_last - INTERVAL '1 day'), t.value INTO res_date_daily, res_val_daily FROM BCRA_reservas_internacionales t WHERE t.date <= (res_date_last - INTERVAL '1 day') ORDER BY t.date DESC LIMIT 1;
    SELECT (res_date_last - INTERVAL '1 month'), t.value INTO res_date_monthly, res_val_monthly FROM BCRA_reservas_internacionales t WHERE t.date <= (res_date_last - INTERVAL '1 month') ORDER BY t.date DESC LIMIT 1;
    SELECT (res_date_last - INTERVAL '1 year'), t.value INTO res_date_yearly, res_val_yearly FROM BCRA_reservas_internacionales t WHERE t.date <= (res_date_last - INTERVAL '1 year') ORDER BY t.date DESC LIMIT 1;
    SELECT (res_date_last - INTERVAL '2 years'), t.value INTO res_date_2years, res_val_2years FROM BCRA_reservas_internacionales t WHERE t.date <= (res_date_last - INTERVAL '2 years') ORDER BY t.date DESC LIMIT 1;
    SELECT (res_date_last - INTERVAL '3 years'), t.value INTO res_date_3years, res_val_3years FROM BCRA_reservas_internacionales t WHERE t.date <= (res_date_last - INTERVAL '3 years') ORDER BY t.date DESC LIMIT 1;
    SELECT (res_date_last - INTERVAL '5 years'), t.value INTO res_date_5years, res_val_5years FROM BCRA_reservas_internacionales t WHERE t.date <= (res_date_last - INTERVAL '5 years') ORDER BY t.date DESC LIMIT 1;
    SELECT (res_date_last - INTERVAL '10 years'), t.value INTO res_date_10years, res_val_10years FROM BCRA_reservas_internacionales t WHERE t.date <= (res_date_last - INTERVAL '10 years') ORDER BY t.date DESC LIMIT 1;

    RETURN NEXT;
END;
$$;


